/**
 * Fixed live feed registry.
 *
 * Security property: the only URLs the importer will ever fetch are the ones
 * listed here (or the single operator override env var). A query parameter can
 * select *which* registry entry to read, never *where* to fetch from, so the
 * endpoint cannot be turned into an open proxy.
 */
import type { LiveSource } from './types';

/** Canonical public playlist (generated by iptv-org into their static site). */
const IPTV_ORG_SITE = 'https://iptv-org.github.io/iptv';
/** Same generated data, served straight from the repository. Independent of the site host. */
const IPTV_ORG_RAW = 'https://raw.githubusercontent.com/iptv-org/iptv/master/streams';

export const LIVE_SOURCES: Record<'iq' | 'arab' | 'world', LiveSource> = {
  iq: {
    key: 'iptv-org:iq',
    label: 'Iraq',
    url: `${IPTV_ORG_SITE}/countries/iq.m3u`,
    mirrors: [`${IPTV_ORG_RAW}/iq.m3u`],
    category: 'العراق · Iraq',
    region: 'iq',
  },
  arab: {
    key: 'iptv-org:arab',
    label: 'Arab region',
    url: `${IPTV_ORG_SITE}/regions/arab.m3u`,
    mirrors: [],
    category: 'المنطقة العربية · Arab',
    region: 'arab',
  },
  world: {
    key: 'iptv-org:world',
    label: 'World',
    url: `${IPTV_ORG_SITE}/index.m3u`,
    mirrors: [],
    category: 'العالم · World',
    region: 'world',
  },
};

/**
 * The operator's own playlist, when configured. It is read from an environment
 * variable or a file on disk, never from a request. It is listed first so its
 * channels win on duplicates.
 */
export function operatorSource(): LiveSource | null {
  const inline = process.env.CLOUDPLAY_LIVE_FEED_INLINE;
  const url = process.env.CLOUDPLAY_LIVE_FEED_URL;
  if (!inline && !url) return null;
  return {
    key: 'operator',
    label: 'Operator',
    url: url ?? '',
    mirrors: [],
    category: 'مخصص · Curated',
    region: 'operator',
  };
}

/** Maximum bytes accepted from a single feed. */
export const FEED_MAX_BYTES = 8 * 1024 * 1024;
/** Maximum redirect hops followed while fetching a feed. */
export const FEED_MAX_REDIRECTS = 3;
/** Feed fetch timeout. */
export const FEED_TIMEOUT_MS = 8000;
/** How long a fresh snapshot is served before a refresh is attempted. */
export const FEED_TTL_MS = 10 * 60 * 1000;
/** Served-but-stale window: after this the data is reported as stale in health. */
export const FEED_STALE_MS = 6 * 60 * 60 * 1000;
